r = op.open(BASE + "/orders/index.php", timeout=10)
html = r.read().decode("utf-8", "replace")
print("MEMBER_SESSION", r.status, "OWN_DETAIL_LINKS", sorted(set(__import__("re").findall(r"detail\.php\?id=(\d+)", html))))

def fetch(i):
    req = urllib.request.Request(BASE + "/orders/detail.php?id=%d" % i)
    req.add_header("Accept", "application/json")
    try:
        x = op.open(req, timeout=10)
        return x.status, x.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode("utf-8", "replace")

for i in range(1, 9):
